'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE='https://plan-ex.ru/erpv2/',U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P16_OUT||'P16_finance_discovery_output');fs.mkdirSync(OUT,{recursive:true});const COMPANY=27,OWNER='p14_owner_260804221827';
function creds(){const e=process.env.P16_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function sa(){return creds().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function login(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(400);ok=!/\/login(?:[/?#]|$)/.test(p.url())}catch{}return{c,p,ok}}
function candidates(t,v){const a=[...v];for(const m of String(t).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==OWNER&&!x.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(x))}
async function owner(b){const s=sa(),x=await login(b,s.username,s.password);if(!x.ok)throw Error('superadmin login failed');await x.p.goto(U(`superadmin/companies/${COMPANY}/users`),{waitUntil:'domcontentloaded'});const f=x.p.locator(`form[action$="/superadmin/companies/${COMPANY}/owner/reset-password"]`).first(),n=x.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await n;const vals=await x.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(y=>y.value||y.textContent||'').filter(Boolean)),list=candidates(await x.p.locator('body').innerText(),vals);await x.c.close();for(const q of list){const y=await login(b,OWNER,q);if(y.ok)return y;await y.c.close()}throw Error('owner login failed')}
async function inspect(p,item){await p.goto(U(item.path),{waitUntil:'domcontentloaded',timeout:45000});const body=await p.locator('body').innerText();let clicked=null;for(const re of item.buttons){const b=p.locator('button,a').filter({hasText:re}).first();if(await b.count()){await b.click();await p.waitForTimeout(400);clicked=String(re);break}}const forms=await p.locator('form').evaluateAll(ns=>ns.filter(n=>n.getBoundingClientRect().width>0||n.querySelector('input,select,textarea')).map(n=>({id:n.id,action:n.getAttribute('action'),method:n.method,enctype:n.enctype,visible:n.getBoundingClientRect().width>0,inputs:[...n.elements].map(e=>({name:e.name,type:e.type,value:e.type==='password'?'[REDACTED]':String(e.value||'').slice(0,200),required:e.required,disabled:e.disabled,options:e.tagName==='SELECT'?[...e.options].map(o=>({value:o.value,text:o.textContent.trim()})).slice(0,40):undefined})).filter(x=>x.name)})));const buttons=await p.locator('button:visible,a:visible').evaluateAll(ns=>ns.map(n=>({text:(n.innerText||'').trim(),href:n.getAttribute('href'),type:n.type,form:n.getAttribute('form')})).filter(x=>x.text));await p.screenshot({path:path.join(OUT,`P16_${item.id}_DISCOVERY_1920x1080.png`),fullPage:false});return{id:item.id,path:item.path,clicked,body:body.replace(/\s+/g,' ').slice(0,5000),forms,buttons}}
(async()=>{const r={status:'FAIL',pages:[],consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[],error:null};let b,o;try{b=await chromium.launch({headless:true});o=await owner(b);const p=o.p;p.on('console',m=>{if(m.type()==='error')r.consoleErrors.push(m.text())});p.on('pageerror',e=>r.pageErrors.push(String(e.message||e)));p.on('requestfailed',q=>r.requestFailures.push(q.url()));p.on('response',z=>{if(z.status()>=500)r.httpFailures.push({status:z.status(),url:z.url()})});const items=[{id:'BANK_ACCOUNTS',path:'company/finance/bank-accounts',buttons:[/Добавить счёт/i,/Создать счёт/i,/Добавить/i]},{id:'CASH',path:'company/finance/cash',buttons:[/Внести/i,/Приход/i,/Создать/i]},{id:'INVOICES',path:'company/finance/invoices',buttons:[/Создать счёт/i,/Добавить/i]},{id:'OPERATIONS',path:'company/finance/operations',buttons:[/Создать/i,/Добавить/i]},{id:'MATCHING',path:'company/finance/settings/matching-rules',buttons:[/Создать/i,/Добавить/i]},{id:'DDS',path:'company/finance/settings/dds-categories',buttons:[/Создать статью/i,/Добавить/i]}];for(const item of items)r.pages.push(await inspect(p,item));r.status=r.pageErrors.length===0&&r.requestFailures.length===0&&r.httpFailures.length===0?'PASS':'FAIL'}catch(e){r.error={name:e.name||'Error',message:String(e.message||e).slice(0,800)}}finally{if(o?.c)await o.c.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P16_FINANCE_FORM_DISCOVERY.json'),JSON.stringify(r,null,2));console.log('P16_FINANCE_DISCOVERY='+r.status);process.exitCode=r.status==='PASS'?0:1}})();
